begin;
alter function public.wm_commercial_command(uuid,text,jsonb,text) rename to wm_commercial_command_before_closure;
revoke all on function public.wm_commercial_command_before_closure(uuid,text,jsonb,text) from public,anon,authenticated;
create function public.wm_commercial_command(p_org uuid,p_command text,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
begin
 if p_command='milestone.due' then
  perform wm.require_access(p_org,'delivery');
  if exists(select 1 from wm.milestones m join wm.engagements e on e.organization_id=m.organization_id and e.id=m.engagement_id where m.organization_id=p_org and m.id=(p_input->>'id')::uuid and e.service_state in ('ending','closed')) then raise exception 'Service closure prevents starting another milestone' using errcode='42501';end if;
 end if;
 return public.wm_commercial_command_before_closure(p_org,p_command,p_input,p_key);
end $$;
alter function public.wm_billing_command(uuid,text,jsonb,text) rename to wm_billing_command_before_minor_validation;
revoke all on function public.wm_billing_command_before_minor_validation(uuid,text,jsonb,text) from public,anon,authenticated;
create function public.wm_billing_command(p_org uuid,p_command text,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
begin
 if p_command='billing.refund' and (p_input->>'amount_minor' is null or p_input->>'amount_minor' !~ '^[1-9][0-9]*$') then raise exception 'Refund amount must be whole minor units' using errcode='22023';end if;
 return public.wm_billing_command_before_minor_validation(p_org,p_command,p_input,p_key);
end $$;
create table wm.closure_statements(
 organization_id uuid not null,id uuid not null default gen_random_uuid(),closure_id uuid not null,
 sequence bigint not null,basis_digest text not null,snapshot jsonb not null,recorded_by uuid not null,created_at timestamptz not null default now(),
 primary key(organization_id,id),unique(organization_id,closure_id,sequence),
 foreign key(organization_id,closure_id) references wm.closures(organization_id,id)
);
alter table wm.closure_statements enable row level security;
revoke all on wm.closure_statements from public,anon,authenticated;
create trigger closure_statement_immutable before update or delete on wm.closure_statements for each row execute function wm.reject_history_edit();
create function wm.billing_earning_policy() returns trigger language plpgsql volatile security definer set search_path='' as $$
declare policy text;
begin
 select component->>'earning_policy' into policy from wm.agreements a join wm.revisions r on r.organization_id=a.organization_id and r.id=a.revision_id cross join lateral jsonb_array_elements(coalesce(r.manifest->'components','[]')) component where a.organization_id=new.organization_id and a.id=new.agreement_id and component->>'id'=new.component;
 new.cancellation_policy:=new.cancellation_policy||jsonb_build_object('earning_policy',coalesce(policy,'completed_work'));
 return new;
end $$;
create trigger freeze_accepted_earning_policy before insert on wm.billing_schedules for each row execute function wm.billing_earning_policy();
create function wm.closure_digest(basis jsonb) returns text language sql immutable set search_path='' as $$
 select wm.hash_json(basis||jsonb_build_object('lines',(select coalesce(jsonb_agg(value-'version'-'observed_at'),'[]') from jsonb_array_elements(basis->'lines')),'adjustments',(select coalesce(jsonb_agg(value-'version'-'observed_at'),'[]') from jsonb_array_elements(basis->'adjustments'))))
$$;

create function wm.closure_basis(org uuid,closure uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare c wm.closures;lines jsonb;adjustments jsonb;
begin
 select * into c from wm.closures where organization_id=org and id=closure;
 if not found then raise exception 'Closure unavailable' using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object(
  'id',o.id,'version',o.version,'description',o.description,'currency',o.currency,'amount_minor',o.amount_minor,
  'paid_minor',o.amount_paid_minor,'provider_state',o.provider_state,'invoice_id',o.invoice_id,'observed_at',o.observed_at,'period_start',o.period_start,'period_end',o.period_end,
  'interval',s.interval,'timezone',s.billing_timezone,'component',s.component,
  'period_days',case when s.interval<>'once' then extract(epoch from ((o.period_end at time zone s.billing_timezone)-(o.period_start at time zone s.billing_timezone)))/86400 end,
  'earned_minor',case when s.interval<>'once' and s.cancellation_policy->>'earning_policy'='actual_days' then round(o.amount_minor*greatest(0,least(1,
    extract(epoch from ((c.effective_at at time zone s.billing_timezone)-(o.period_start at time zone s.billing_timezone)))::numeric/
    nullif(extract(epoch from ((o.period_end at time zone s.billing_timezone)-(o.period_start at time zone s.billing_timezone))),0))))::bigint
   when m.id is not null then m.earned_minor else null end,
  'earned_basis',case when s.interval<>'once' and s.cancellation_policy->>'earning_policy'='actual_days' then 'Actual calendar days through the effective end in the agreed billing timezone.' when m.id is not null then 'Verified milestone earnings.' else 'Finance must itemize completed agreed work and any remaining delivery obligation under the accepted terms.' end,
  'milestone_version',m.version) order by o.period_start,o.id),'[]') into lines
 from wm.billing_obligations o join wm.billing_schedules s on s.organization_id=o.organization_id and s.id=o.schedule_id
 left join wm.milestones m on m.organization_id=s.organization_id and s.component='milestone:'||m.id::text
 where o.organization_id=org and o.engagement_id=c.engagement_id;
 -- Earned work can remain owed even when invoice preparation never occurred.
 select lines||coalesce(jsonb_agg(jsonb_build_object('id',m.id,'source','uninvoiced_milestone','version',m.version,'description',m.deliverable,'currency',m.currency,'amount_minor',m.amount_minor,'paid_minor',0,'provider_state','not_invoiced','invoice_id',null,'observed_at',null,'interval','once','earned_minor',m.earned_minor,'earned_basis','Verified earned milestone not yet invoiced.','milestone_version',m.version) order by m.id),'[]') into lines
 from wm.milestones m where m.organization_id=org and m.engagement_id=c.engagement_id and m.earned_minor>0 and not exists(select 1 from wm.billing_obligations o join wm.billing_schedules s on s.organization_id=o.organization_id and s.id=o.schedule_id where o.organization_id=org and s.component='milestone:'||m.id::text);
 select coalesce(jsonb_agg(jsonb_build_object('id',f.id,'version',f.version,'amount_minor',f.amount_minor,'state',f.state,'provider_id',f.provider_id,'observed_at',f.observed_at) order by f.id),'[]') into adjustments from wm.financial_adjustments f where f.organization_id=org and f.engagement_id=c.engagement_id;
 return jsonb_build_object('closure_id',c.id,'effective_at',c.effective_at,'timing',c.timing,'exit_mode',c.exit_mode,'lines',lines,'adjustments',adjustments);
end $$;

create function public.wm_closure_command(p_org uuid,p_command text,p_input jsonb,p_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare c wm.closures;result jsonb;basis jsonb;item jsonb;entry jsonb;items jsonb:='[]';earned bigint;tax_credit bigint;received bigint;service_paid bigint;tax_paid bigint;other_paid bigint;pre_tax_return bigint;seq bigint;rid uuid;st wm.closure_statements;
begin
 perform wm.require_access(p_org,'finance');perform wm.require_recent_auth();
 if p_command<>'closure.statement' then raise exception 'Unsupported closure action' using errcode='22023';end if;
 perform wm.check_input(p_input,array['closure_id','expected_version','basis_digest','lines','tax_evidence','summary'],array['closure_id','expected_version','basis_digest','lines','tax_evidence','summary']);
 result:=wm.prior_command(p_org,p_command,p_key,p_input);if result is not null then return result;end if;
 select * into c from wm.closures where organization_id=p_org and id=(p_input->>'closure_id')::uuid for update;
 if not found then raise exception 'Closure unavailable' using errcode='42501';end if;
 perform wm.check_version(c.version,(p_input->>'expected_version')::bigint);
 basis:=wm.closure_basis(p_org,c.id);
 if p_input->>'basis_digest' is distinct from wm.closure_digest(basis) then raise exception 'Billing changed; review the current statement inputs' using errcode='40001';end if;
 if jsonb_typeof(p_input->'lines') is distinct from 'array' or jsonb_array_length(p_input->'lines')<>jsonb_array_length(basis->'lines') then raise exception 'Review every invoice line' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(basis->'lines') loop
  select value into entry from jsonb_array_elements(p_input->'lines') where value->>'id'=item->>'id';
  if entry is null or (select count(*) from jsonb_array_elements(p_input->'lines') where value->>'id'=item->>'id')<>1 then raise exception 'Each invoice needs one reviewed calculation' using errcode='22023';end if;
  perform wm.check_input(entry,array['id','earned_minor','service_paid_minor','tax_paid_minor','other_paid_minor','tax_credit_minor','evidence'],array['id','earned_minor','service_paid_minor','tax_paid_minor','other_paid_minor','tax_credit_minor','evidence']);
  if entry->>'earned_minor' is null or entry->>'earned_minor' !~ '^[0-9]+$' or entry->>'tax_credit_minor' is null or entry->>'tax_credit_minor' !~ '^[0-9]+$' then raise exception 'Use whole minor units for statement amounts' using errcode='22023';end if;
  if item->>'invoice_id' is not null and (item->>'observed_at' is null or (item->>'observed_at')::timestamptz<now()-interval '1 day') then raise exception 'Reconcile the current invoice before recording a statement' using errcode='42501';end if;
  if exists(select 1 from unnest(array['service_paid_minor','tax_paid_minor','other_paid_minor']) k where entry->>k is null or entry->>k !~ '^[0-9]+$') then raise exception 'Itemize received service fees, tax and overpayments in whole minor units' using errcode='22023';end if;
  service_paid:=(entry->>'service_paid_minor')::bigint;tax_paid:=(entry->>'tax_paid_minor')::bigint;other_paid:=(entry->>'other_paid_minor')::bigint;
  earned:=(entry->>'earned_minor')::bigint;tax_credit:=(entry->>'tax_credit_minor')::bigint;received:=(item->>'paid_minor')::bigint;
  if earned is null or earned<0 or earned>(item->>'amount_minor')::bigint or tax_credit is null or tax_credit<0 or tax_credit>tax_paid or service_paid>(item->>'amount_minor')::bigint or service_paid::numeric+tax_paid+other_paid<>received then raise exception 'Check earned amount and tax credit against the invoice' using errcode='22023';end if;
  if item->>'earned_minor' is not null and earned<>(item->>'earned_minor')::bigint then raise exception 'Use the current verified milestone or actual-day earnings' using errcode='40001';end if;
  perform wm.require_text(entry->>'evidence','completed work and tax evidence');
  pre_tax_return:=greatest(0,service_paid-earned);
  items:=items||jsonb_build_array(item||jsonb_build_object('earned_minor',earned,'calculation_evidence',entry->>'evidence','tax_credit_minor',tax_credit,'service_paid_minor',service_paid,'tax_paid_minor',tax_paid,'other_paid_minor',other_paid,'return_due_minor',pre_tax_return+tax_credit+other_paid,'unpaid_earned_minor',greatest(0,earned-service_paid),'unearned_unpaid_minor',greatest(0,(item->>'amount_minor')::bigint-greatest(earned,service_paid))));
 end loop;
 perform wm.require_text(p_input->>'tax_evidence','tax and credit-note review');perform wm.require_text(p_input->>'summary','settlement explanation');
 if exists(select 1 from wm.operations where organization_id=p_org and engagement_id=c.engagement_id and kind like 'stripe_%' and state in ('pending','in_flight','unknown')) then raise exception 'Reconcile pending financial operations before recording a statement' using errcode='42501';end if;
 select coalesce(max(sequence),0)+1 into seq from wm.closure_statements where organization_id=p_org and closure_id=c.id;
 insert into wm.closure_statements(organization_id,closure_id,sequence,basis_digest,snapshot,recorded_by)
  values(p_org,c.id,seq,wm.closure_digest(basis),basis||jsonb_build_object('lines',items,'tax_evidence',p_input->>'tax_evidence','summary',p_input->>'summary','refund_status','Separate provider verification required'),auth.uid()) returning id into rid;
 update wm.closures set billing_state='statement_recorded',version=version+1 where organization_id=p_org and id=c.id;
 perform wm.critical(p_org,'closure.statement_recorded',rid,jsonb_build_object('closure_id',c.id,'sequence',seq,'basis_digest',wm.closure_digest(basis)));
 return wm.finish_command(p_org,p_command,p_key,p_input,jsonb_build_object('id',rid,'sequence',seq,'version',c.version+1),rid);
end $$;

alter function public.wm_workspace(uuid) rename to wm_workspace_before_statements;
revoke all on function public.wm_workspace_before_statements(uuid) from public,anon,authenticated;
create function public.wm_workspace(p_org uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare r jsonb;finance boolean;
begin
 r:=public.wm_workspace_before_statements(p_org);finance:=wm.operator_has(p_org,'finance') or wm.member_role(p_org)='customer_admin';
 return r||jsonb_build_object('closure_calculations',case when wm.operator_has(p_org,'finance') then (select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'basis',wm.closure_basis(p_org,c.id),'basis_digest',wm.closure_digest(wm.closure_basis(p_org,c.id)))),'[]') from wm.closures c where organization_id=p_org) else '[]'::jsonb end,
 'statements',case when finance then (select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'closure_id',s.closure_id,'sequence',s.sequence,'created_at',s.created_at,'snapshot',s.snapshot,'current',s.basis_digest=wm.closure_digest(wm.closure_basis(p_org,s.closure_id))) order by s.created_at desc),'[]') from wm.closure_statements s where organization_id=p_org) else '[]'::jsonb end);
end $$;
revoke all on all functions in schema wm from public,anon,authenticated;
revoke all on function public.wm_commercial_command(uuid,text,jsonb,text),public.wm_billing_command(uuid,text,jsonb,text),public.wm_closure_command(uuid,text,jsonb,text),public.wm_workspace(uuid) from public,anon;
grant execute on function public.wm_commercial_command(uuid,text,jsonb,text),public.wm_billing_command(uuid,text,jsonb,text),public.wm_closure_command(uuid,text,jsonb,text),public.wm_workspace(uuid) to authenticated;
-- New agreements make their earning policy explicit; accepted old snapshots
-- are retained and never acquire a new time-based earning rule retroactively.
insert into wm.catalog_registry(catalog_id,variant,catalog_version,snapshot,digest) select s->>'id',s->>'variant',s->>'catalog_version',s,wm.hash_json(s) from (values('{"schema":3,"site_required":true,"care_kind":null,"production":false,"basic_measurement_included":true,"advanced_measurement":false,"onboarding_only":false,"id":"launch_site","variant":"standard","name":"Focused Website","service_type":"web_design","catalog_version":"2026-10-29-v4-offers:workspace-3","currency":"USD","scope":"Structured written intake, one audience, one primary inquiry journey and a ten-page plan. Review up to two relevant competitors. An optional 30-minute kickoff can replace the written kickoff. Up to 10 marketing pages with original AI-assisted writing, edited and checked against approved business facts. Content is as concise or detailed as the topic, reader and search intent require; there is no word quota or word-count surcharge for the agreed page purpose. Select and adapt one established W&M layout direction. Apply the client’s logo, colors, typography, spacing and imagery consistently. The client sees the design approach before booking; a newly art-directed visual system is a Custom Website scope. Prepare up to eight supplied/licensed photographs and one simple original website graphic. No original logo, commissioned photography or motion production. One contact form with up to eight fields, one notification destination, spam controls and confirmation; one existing booking/payment tool link or embed. New provider configuration and automations are separate. One agreed supported platform. If needed, one standard content collection with up to six supplied entries using the established component set. Up to three client-supplied policy pages are formatted outside the 10 marketing-page count. Two consolidated review rounds: copy/design direction, then complete preview. Shared launch checks, audit/check record and explicit launch approval. Written editing guide and recorded demonstration; optional 20-minute handoff appointment. Client-controlled domain and service accounts, an ownership/license inventory, checks within two business days and around day 14 after launch, and 30-day defect support. Optional Care is separate. Search-ready page planning: map each agreed service or buyer question to its page; review search intent and relevant query themes, write unique titles/descriptions, connect related pages with internal links, and apply the shared technical search checks. Search demand informs useful content; rankings are not guaranteed. Written communication by default: email or the agreed text channel anytime, with acknowledgement within one business day during active delivery/support. Weekly project updates; optional calls by appointment. No call is required to buy, give feedback or receive the handoff. Launch handover pack: page and account inventory, test/check record, editing guide with recorded demonstration, support dates, and a prioritized next-90-days recommendation sheet. This is a handoff recommendation, not ongoing SEO delivery or a new full audit. Basic inquiry measurement: connect one client-owned GA4 property and Search Console property, and test page views plus one primary inquiry-success event through a supported native integration. Configure one compatible consent tool using client-approved settings where required; its subscription is a disclosed client cost. Excludes GTM/custom tagging, dashboards, cross-domain/server-side tracking and extra events. Confirm platform feasibility before booking; no silent omission if unavailable. Preserve existing working measurement and avoid duplicates.","exclusions":["A new visual identity, original art direction or multiple homepage concepts","Store, portal, custom calculator, conditional form, migration or custom application","New tool-account setup beyond the included basic measurement, original field research, ongoing SEO, social media and advertising"],"acceptance":["All agreed pages, approved copy and supplied policy text are complete.","The selected design approach is consistent across mobile and desktop.","The shared quality checks and audit record are complete, including a tested inquiry destination and confirmation.","The owner explicitly approves launch and receives access, responsibilities and handoff."],"components":[],"milestones":[{"id":"stage_1","deliverable":"Reserve your agreed start","amount_minor":87800,"acceptance_rule":"Reserve your agreed start","proof":"booking"},{"id":"stage_2","deliverable":"Approve copy and design direction","amount_minor":65850,"acceptance_rule":"Approve copy and design direction","proof":"approved_work"},{"id":"stage_3","deliverable":"Approve staging before launch","amount_minor":65850,"acceptance_rule":"Approve staging before launch","proof":"approved_work"}],"entitlements":[],"quote_required":false,"hosting_offset_cap_minor":0,"terms":{"delivery":"Delivery begins at your ready, booked start: approved scope, initial payment, access and business facts in place. The next available start is confirmed separately. Normal review time is included; allow two business days for consolidated feedback at each gate. The shortest targets need prompt approvals. Missing inputs or approved changes can move dates. Written communication is standard; calls are optional.","payment":"Reserve your agreed start: 878.00 USD; Approve copy and design direction: 658.50 USD; Approve staging before launch: 658.50 USD","cancellation":"Use a written reconciliation: pay for completed agreed work and approved nonrecoverable external expenses; return unearned prepaid fees. Define the reconciliation and payment timetable in the proposal instead of calling every deposit nonrefundable. Existing client agreements keep their terms.","ownership":"The client owns the domain and business/platform accounts from the beginning where the provider supports it; W&M uses delegated access. Client-owned pre-existing accounts and data are never withheld as a substitute for collecting a disputed invoice. Transfer agreed original deliverables and editable source files under the project agreement after the relevant fees are paid. Identify licensed fonts, stock media, open-source components, third-party platform restrictions and AI-assisted assets separately. Do not promise exclusive ownership of licensed or generated material.","overlap":"When a module replaces included work, quote only the incremental work. For example, a guided form replacing an included ordinary form removes that ordinary form production/testing line from the build estimate before the upgrade fee is agreed. Retain the acceptance tests that still apply.","measurement":"Basic inquiry measurement: connect one client-owned GA4 property and Search Console property, and test page views plus one primary inquiry-success event through a supported native integration. Configure one compatible consent tool using client-approved settings where required; its subscription is a disclosed client cost. Excludes GTM/custom tagging, dashboards, cross-domain/server-side tracking and extra events. Confirm platform feasibility before booking; no silent omission if unavailable. Preserve existing working measurement and avoid duplicates."},"required_facts":["business_identity","service_goals","approved_claims","primary_contact"],"required_access":["domain","website"]}'::jsonb)) seed(s);
insert into wm.catalog_registry(catalog_id,variant,catalog_version,snapshot,digest) select s->>'id',s->>'variant',s->>'catalog_version',s,wm.hash_json(s) from (values('{"schema":3,"site_required":true,"care_kind":null,"production":false,"basic_measurement_included":true,"advanced_measurement":false,"onboarding_only":false,"id":"focused_site","variant":"standard","name":"Custom Website","service_type":"web_design","catalog_version":"2026-10-29-v4-offers:workspace-3","currency":"USD","scope":"Written discovery workbook and follow-up questions; review up to three competitors, prioritize up to two related service groups, and deliver a page plan plus concise message brief. Optional discovery appointment up to 90 minutes can replace the written exchange. Up to 15 marketing pages with original writing from verified business facts, shaped to the topic, reader and search intent without a word cap. One may be a proof/case-study page from client-supplied evidence and approved statements; it counts inside the 15 pages. An original homepage visual direction and up to three reusable interior page types, designed around the client’s brand and content rather than selecting the Focused plan’s established layout. Responsive desktop/mobile design; existing-logo color/type/image direction. Up to three simple original website graphics and preparation of up to eight supplied or licensed photographs. No mandatory asset quota: agree the useful assets in the page plan. One contact form, up to eight fields, one notification destination, spam controls and a confirmation message. One existing-tool booking or payment link/embed; no new account configuration or workflow automation. One agreed platform and one content collection if needed, with up to six supplied entries. The platform and editing tasks are selected before booking. Shared website launch standards, two consolidated review rounds, a written editing guide, recorded demonstration and ownership/handoff inventory. Optional training appo